#endif
}

__global__ void __launch_bounds__(kThreads, 1) tc_h_kernel(const float* __restrict__ W,
                                                          const __grid_constant__ CUtensorMap mapE1,
                                                          const __grid_constant__ CUtensorMap mapE2,
                                                          const float* __restrict__ bias, OutPtrs outs,
                                                          const float* __restrict__ emb, uint4* emb16, unsigned* sync,
                                                          TileCfg p) {
#if defined(__CUDA_ARCH_FEAT_SM100_ALL)
  extern __shared__ uint8_t smem_raw[];
  __shared__ __align__(8) uint64_t full[kMaxStages], empty[kMaxStages], accum, tfree, stg, sfree;
  __shared__ uint32_t tmem_slot;
  const uint32_t sbase = (smem_u32(smem_raw) + 1023) & ~1023u;
  const int eb1 = p.n1 / 2, eb2 = p.n2 / 2;                      // emb rows per CTA for each accumulator
  const uint32_t e1Off = kABlk, e2Off = e1Off + eb1 * 128;
  const uint32_t embBytes = (eb1 + eb2) * 128, stageBytes = kABlk + embBytes;   // per CTA, multiple of 1024
  const int warp = __shfl_sync(0xffffffffu, threadIdx.x >> 5, 0), lane = threadIdx.x & 31;
