  asm volatile("mov.u32 %0, %%cluster_ctarank;" : "=r"(rank));
  const int pair = blockIdx.x >> 1, npairs = gridDim.x >> 1;
  auto m0_of = [&](int j) { return (((pair + npairs * j) / p.nb) * 2 + (int)rank) * kRows; };
  auto boff_of = [&](int j) { return ((pair + npairs * j) % p.nb) * p.ntile; };
  // this CTA's slice of emb in 8-float units
  const int lo = (int)((long long)p.n8 * blockIdx.x / gridDim.x), hi = (int)((long long)p.n8 * (blockIdx.x + 1) / gridDim.x);
  if (threadIdx.x == 0) {
    for (int i = 0; i < p.stages; ++i) {
      mbar_init(smem_u32(&full[i]), 3);   // leader's emb expect_tx + one converter-group arrive per CTA
      mbar_init(smem_u32(&empty[i]), 1);
    }
    mbar_init(smem_u32(&accum), 1);
    mbar_init(smem_u32(&tfree), 2);       // one arrive per CTA after its epilogue has read TMEM
    mbar_init(smem_u32(&stg), 1);
    mbar_init(smem_u32(&sfree), 1);
    asm volatile("fence.mbarrier_init.release.cluster;");
    if (p.fuse) {   // fp32 emb slice -> stage area (unused until the first W stores / emb TMA)
      const uint32_t bytes = (uint32_t)(hi - lo) * 32, sb = smem_u32(&stg);
      asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" ::"r"(sb), "r"(bytes) : "memory");
      asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];"
                   ::"r"(sbase), "l"(emb + (size_t)lo * 8), "r"(bytes), "r"(sb) : "memory");
    }
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapE1) : "memory");
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapE2) : "memory");
  }
  if (warp == 3) {
    asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(smem_u32(&tmem_slot)), "r"(p.tmem_cols));
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::2.sync.aligned;");
  }
