  asm volatile("tcgen05.fence::after_thread_sync;");
  const uint32_t tmem = tmem_slot;

  if (p.fuse && warp < kCvtWarp0) {   // emb slice: fp32 staging -> fp16 global scratch, then count this CTA in
    mbar_wait(smem_u32(&stg), 0);
    for (int u = lo + (int)threadIdx.x; u < hi; u += 32 * kCvtWarp0) {
      const uint32_t a = sbase + (uint32_t)(u - lo) * 32;
      const float4 x = lds128(a), y = lds128(a + 16);
      emb16[u] = make_uint4(pack_h2(x.x, x.y), pack_h2(x.z, x.w), pack_h2(y.x, y.y), pack_h2(y.z, y.w));
    }
    asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
    asm volatile("bar.sync %0, %1;" ::"r"(2 + kGroups), "r"(32 * kCvtWarp0) : "memory");
    if (threadIdx.x == 0) {
      asm volatile("red.release.gpu.global.add.u32 [%0], 1;" ::"l"(sync) : "memory");
      asm volatile("mbarrier.arrive.shared::cta.b64 _, [%0];" ::"r"(smem_u32(&sfree)) : "memory");
    }
  }

