      }
      __syncwarp();
      asm volatile("fence.proxy.async.global;" ::: "memory");
    }
    for (int j = 0; j < p.nb; ++j) {
      const int boff = boff_of(j);
      for (int kb = 0; kb < kKB; ++kb) {
        const int t = j * kKB + kb, s = t % p.stages;
        if (t >= p.stages) mbar_wait(smem_u32(&empty[s]), ((t / p.stages) - 1) & 1);
        if (elect_one()) {
          const uint32_t fl = smem_u32(&full[s]);
          const uint32_t fb = mapa0(fl);   // the leader's full barrier collects the bytes of both CTAs
          if (rank == 0)
            asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" ::"r"(fl), "r"(2 * embBytes) : "memory");
          const uint32_t a = sbase + s * stageBytes;
          tma_e(a + e1Off, &mapE1, fb, kb * kBK, boff + (int)rank * eb1);
          if (p.n2) tma_e(a + e2Off, &mapE2, fb, kb * kBK, boff + p.n1 + (int)rank * eb2);
        }
        __syncwarp();
      }
    }
  } else if (warp == 1 && rank == 0) {   // MMA issuer (leader, whole warp waits, one lane issues)
    const uint32_t idesc1 = (1u << 4) | ((uint32_t)(p.n1 >> 3) << 17) | ((uint32_t)(2 * kRows >> 4) << 24);
    const uint32_t idesc2 = (1u << 4) | ((uint32_t)(p.n2 >> 3) << 17) | ((uint32_t)(2 * kRows >> 4) << 24);
    for (int j = 0; j < p.nb; ++j) {
      if (j > 0) {   // both CTAs have drained the previous item's accumulators
        mbar_wait_cluster(smem_u32(&tfree), (j - 1) & 1);
        asm volatile("tcgen05.fence::after_thread_sync;");
      }
      for (int kb = 0; kb < kKB; ++kb) {
        const int t = j * kKB + kb, s = t % p.stages;
        mbar_wait_cluster(smem_u32(&full[s]), (t / p.stages) & 1);
        asm volatile("tcgen05.fence::after_thread_sync;");
        const uint32_t a = sbase + s * stageBytes;
        const uint64_t da = sw128_desc(a), db = sw128_desc(a + e1Off), dc = sw128_desc(a + e2Off);
        if (elect_one()) {
#pragma unroll
          for (int k = 0; k < kBK / 16; ++k) {   // UMMA K = 16 fp16 = 32 B along the swizzled row
            const uint32_t acc = (kb | k) != 0;
            umma2(tmem, da + 2 * k, db + 2 * k, idesc1, acc);
            if (p.n2) umma2(tmem + 256, da + 2 * k, dc + 2 * k, idesc2, acc);
          }
          umma_commit2(smem_u32(&empty[s]));
        }
        __syncwarp();
      }
      if (elect_one()) umma_commit2(smem_u32(&accum));
      __syncwarp();
    }
  } else if (warp >= kCvtWarp0) {   // W converters: global fp32 -> registers -> fp16 SW128 stage, G rotating groups
    const int cw = warp - kCvtWarp0, g = cw / kGroupWarps, w = cw % kGroupWarps;
    const int half = lane >> 4, c4 = lane & 15, jj = c4 >> 1;
    const int rb = w * 16 + half;   // rows rb + 2 i; floats 4 c4 .. 4 c4 + 3 = half (c4 & 1) of 16-B fp16 chunk jj
    const float* src = W + (size_t)(m0_of(0) + rb) * kD + c4 * 4;
    uint32_t sOff[8];
#pragma unroll
    for (int i = 0; i < 8; ++i) {
      const int r = rb + 2 * i;
      sOff[i] = r * 128 + ((jj ^ (r & 7)) << 4) + (c4 & 1) * 8;
    }
    uint64_t pol;
    asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    const uint32_t fullL = mapa0(smem_u32(&full[0]));
    float4 buf[8];
    load_kb(buf, src, g, pol);
    for (int j = 0; j < p.nb; ++j) {
      for (int kb = g; kb < kKB; kb += kGroups) {
        const int t = j * kKB + kb, s = t % p.stages;
        if (t >= p.stages) mbar_wait(smem_u32(&empty[s]), ((t / p.stages) - 1) & 1);
        else if (p.fuse) mbar_wait(smem_u32(&sfree), 0);   // the emb staging in the stage area has been read
        const uint32_t a = sbase + s * stageBytes;
#pragma unroll
        for (int i = 0; i < 8; ++i) {
          const float4 x = buf[i];
          sts64(a + sOff[i], pack_h2(x.x, x.y), pack_h2(x.z, x.w));
        }
        asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
        // no loads in flight here: every lane's buffer was consumed by the stores above
        asm volatile("bar.sync %0, %1;" ::"r"(1 + g), "r"(32 * kGroupWarps) : "memory");
        if (w == 0) {
          if (elect_one()) arrive_cluster(fullL + 8 * s);
          __syncwarp();
        }
        if (kb + kGroups < kKB) load_kb(buf, src, kb + kGroups, pol);
      }
      if (j + 1 < p.nb) {   // next item's first k-block loads fly while this item's accumulator is drained
        src = W + (size_t)(m0_of(j + 1) + rb) * kD + c4 * 4;
        load_kb(buf, src, g, pol);
        epilogue(j, cw >> 2, kCvtWarps / 4);
        asm volatile("tcgen05.fence::before_thread_sync;");
        asm volatile("bar.sync %0, %1;" ::"r"(1 + kGroups), "r"(32 * kCvtWarps) : "memory");
        if (cw == 0) {
          if (elect_one()) arrive_cluster(mapa0(smem_u32(&tfree)));
          __syncwarp();
        }
      }
    }
  }

  if (p.nb == 1) epilogue(0, warp >> 2, kThreads / 128);
  else if (warp >= kCvtWarp0) epilogue(p.nb - 1, (warp - kCvtWarp0) >> 2, kCvtWarps / 4);
  asm volatile("tcgen05.fence::before_thread_sync;");
  cluster_sync();
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(p.tmem_cols));
  }
#endif
}
