__device__ __forceinline__ void arrive_cluster(uint32_t bar) { asm volatile("mbarrier.arrive.release.cluster.shared::cluster.b64 _, [%0];" ::"r"(bar) : "memory"); }
__device__ __forceinline__ void arrive_cluster_relaxed(uint32_t bar) { asm volatile("mbarrier.arrive.relaxed.cluster.shared::cluster.b64 _, [%0];" ::"r"(bar) : "memory"); }
#endif
#ifdef TL
__device__ unsigned long long g_tl[2 * kPairs * 32];
__device__ __forceinline__ void tl_rec(int i) { unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t)); g_tl[blockIdx.x * 32 + i] = t; }
#define TLX(cond, i) do { if (cond) tl_rec(i); } while (0)
