#endif
}
template <bool kEpi>
__global__ void __launch_bounds__(kEpi ? kThreadsE : kThreads, 1) tc_h_kernel(const float* __restrict__ W,
    const __grid_constant__ CUtensorMap mapE1, const __grid_constant__ CUtensorMap mapE2, const float* __restrict__ bias, OutPtrs outs,
