    const uint32_t idesc2 = (1u << 4) | ((uint32_t)(p.n2 >> 3) << 17) | ((uint32_t)(2 * kRows >> 4) << 24);
    auto wait_full = [&](int t) { mbar_wait_cluster(smem_u32(&full[t % p.stages]), (t / p.stages) & 1); asm volatile("tcgen05.fence::after_thread_sync;"); };
