static int g_ovr[4] = {-1, -1, -1, -1};
extern "C" void adamod_tc_h_ovr(int tail, int head, int stages, int epi) { g_ovr[0] = tail; g_ovr[1] = head; g_ovr[2] = stages; g_ovr[3] = epi; }
