extern "C" int adamod_tc_h(const float* emb, const float* W, const float* bias, float* const* outs, void* emb16, int B, cudaStream_t stream) {
  if (B < 1 || B > 1024 || emb16 == nullptr) return 430;
  TileCfg p;
  p.B = B; p.nb = B <= 512 ? 1 : 2;
  p.ntile = ((B + p.nb - 1) / p.nb + 15) / 16 * 16;
  p.n1 = p.ntile < 256 ? p.ntile : 256; p.n2 = p.ntile - p.n1;
  p.tmem_cols = p.n2 ? 512 : p.n1 <= 32 ? 32 : p.n1 <= 64 ? 64 : p.n1 <= 128 ? 128 : 256;
