  bool epi = p.nb == 2;
  if (g_ovr[2] > 0) maxStages = g_ovr[2];
  if (g_ovr[3] >= 0) epi = g_ovr[3] != 0;
  p.stages = (kSmemDyn - 1024) / stageBytes;
  if (p.stages > maxStages) p.stages = maxStages;
  if (p.stages < kGroups) return 433;
  p.tail = epi ? p.stages : 0;
  p.head = epi ? (kCvtDrainOn && p.stages > kGroups ? kGroups : p.stages) : 0;
  if (g_ovr[0] >= 0) p.tail = g_ovr[0] < p.stages ? g_ovr[0] : p.stages;
  if (g_ovr[1] >= 0) p.head = g_ovr[1] < p.stages ? g_ovr[1] : p.stages;
  const int grid = 2 * kPairs;
