//   131 < B <= 256: 2SM pair kernel with 2-k-block stages (tc_pair.cu, r3).
//   B >  256: warp-specialised 2SM kind::f16 kernel with rotating converter groups (tc_h.cu, r7), one launch of 72
//             persistent pairs with the fp16 emb conversion fused in (r8).
extern "C" int adamod_tc_small(const float*, const float*, const float*, float* const*, int, cudaStream_t);
extern "C" int adamod_tc_pair(const float*, const float*, const float*, float* const*, int, cudaStream_t);
extern "C" int adamod_tc_h(const float*, const float*, const float*, float* const*, void*, int, cudaStream_t);

extern "C" int adamod_needs_emb16(int B) { return B > 256; }

extern "C" int adamod_launch(const float* emb, const float* weight, const float* bias, float* const* outs, void* emb16,
                             int B, cudaStream_t stream) {
