  p.stages = (kSmemDyn - 1024) / stageBytes;
  if (p.stages > maxStages) p.stages = maxStages;
  if (p.stages < kGroups) return 433;
  const bool epi = p.nb == 2;   // r11: dedicated epilogue warps and accumulator-0-first ordering at nb = 2
  p.tail = epi ? p.stages : 0;
  p.head = epi ? p.stages : 0;
